    // Run a scenario: deposit some ether, set MinSum, then attempt Collect and check relation
    function run(uint depositAmt, uint minSum, uint collectAmt) public payable {
        require(address(this).balance >= depositAmt, "not enough ether for deposit");

        // Ensure initial MinSum and Log can be set before initialization
        c.SetMinSum(minSum);

        // Perform a deposit into c from this contract
        c.Deposit{value: depositAmt}();

        // Read balance recorded for this contract before collect
        uint beforeBal = c.balances(address(this));
        uint contractBalBefore = address(c).balance;

        // Attempt Collect and capture whether it reverted
        bool reverted;
        try c.Collect(collectAmt) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterBal = c.balances(address(this));
        uint contractBalAfter = address(c).balance;

        // General rule asserted:
        // If Collect succeeded (not reverted) then:
        //  - beforeBal >= minSum and beforeBal >= collectAmt (preconditions satisfied)
        //  - the recorded balance decreased by exactly collectAmt
        //  - the contract's ether balance decreased by at least collectAmt
        // If Collect reverted then at least one of (beforeBal < minSum, beforeBal < collectAmt) held or the transfer failed.
        assert(
            (!reverted && beforeBal >= minSum && beforeBal >= collectAmt && afterBal + collectAmt == beforeBal && contractBalBefore >= contractBalAfter && contractBalBefore - contractBalAfter >= collectAmt)
            || (reverted && (beforeBal < minSum || beforeBal < collectAmt || contractBalBefore < collectAmt))
        );
    }

    // receive to accept refunds if any
    receive() external payable {}
}

